import { test, expect } from '@playwright/test';

test.describe('Reorder list items by drag and drop', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('data:text/html,<html><body><div id="app"><ul id="sortable-list"><li draggable="true" data-id="1">Item 1</li><li draggable="true" data-id="2">Item 2</li><li draggable="true" data-id="3">Item 3</li><li draggable="true" data-id="4">Item 4</li></ul></div><script>const list = document.getElementById("sortable-list"); list.addEventListener("dragstart", (e) => { e.dataTransfer.effectAllowed = "move"; e.dataTransfer.setData("text/html", e.target.innerHTML); e.target.style.opacity = "0.5"; }); list.addEventListener("dragend", (e) => { e.target.style.opacity = "1"; }); list.addEventListener("dragover", (e) => { e.preventDefault(); e.dataTransfer.dropEffect = "move"; }); list.addEventListener("drop", (e) => { e.preventDefault(); const draggedElement = document.querySelector("li[style*=opacity]"); if (e.target.tagName === "LI" && draggedElement !== e.target) { const allItems = Array.from(list.querySelectorAll("li")); const draggedIndex = allItems.indexOf(draggedElement); const targetIndex = allItems.indexOf(e.target); if (draggedIndex < targetIndex) { e.target.parentNode.insertBefore(draggedElement, e.target.nextSibling); } else { e.target.parentNode.insertBefore(draggedElement, e.target); } } }); </script></body></html>');
  });

  test('should reorder list items by dragging item down', async ({ page }) => {
    const listItems = page.getByRole('listitem');

    // Verify initial order
    await expect(listItems.nth(0)).toContainText('Item 1');
    await expect(listItems.nth(1)).toContainText('Item 2');
    await expect(listItems.nth(2)).toContainText('Item 3');
    await expect(listItems.nth(3)).toContainText('Item 4');

    // Drag Item 1 to position after Item 3
    const item1 = listItems.nth(0);
    const item3 = listItems.nth(2);

    await item1.dragTo(item3);

    // Wait for DOM to update
    await page.waitForTimeout(100);

    // Verify new order after drag
    const updatedItems = page.getByRole('listitem');
    await expect(updatedItems.nth(0)).toContainText('Item 2');
    await expect(updatedItems.nth(1)).toContainText('Item 3');
    await expect(updatedItems.nth(2)).toContainText('Item 1');
    await expect(updatedItems.nth(3)).toContainText('Item 4');
  });

  test('should reorder list items by dragging item up', async ({ page }) => {
    const listItems = page.getByRole('listitem');

    // Verify initial order
    await expect(listItems.nth(0)).toContainText('Item 1');
    await expect(listItems.nth(1)).toContainText('Item 2');
    await expect(listItems.nth(2)).toContainText('Item 3');
    await expect(listItems.nth(3)).toContainText('Item 4');

    // Drag Item 4 to position before Item 2
    const item4 = listItems.nth(3);
    const item2 = listItems.nth(1);

    await item4.dragTo(item2);

    // Wait for DOM to update
    await page.waitForTimeout(100);

    // Verify new order after drag
    const updatedItems = page.getByRole('listitem');
    await expect(updatedItems.nth(0)).toContainText('Item 1');
    await expect(updatedItems.nth(1)).toContainText('Item 4');
    await expect(updatedItems.nth(2)).toContainText('Item 2');
    await expect(updatedItems.nth(3)).toContainText('Item 3');
  });

  test('should maintain list integrity after multiple reorders', async ({ page }) => {
    const listItems = page.getByRole('listitem');

    // First reorder: Move Item 1 after Item 3
    await listItems.nth(0).dragTo(listItems.nth(2));
    await page.waitForTimeout(100);

    // Second reorder: Move Item 4 to the beginning
    let currentItems = page.getByRole('listitem');
    await currentItems.nth(3).dragTo(currentItems.nth(0));
    await page.waitForTimeout(100);

    // Verify all items are still present and in expected order
    currentItems = page.getByRole('listitem');
    const itemCount = await currentItems.count();
    expect(itemCount).toBe(4);

    // Verify no items are duplicated or missing
    const itemTexts: string[] = [];
    for (let i = 0; i < itemCount; i++) {
      const text = await currentItems.nth(i).textContent();
      itemTexts.push(text || '');
    }

    expect(itemTexts).toContain('Item 1');
    expect(itemTexts).toContain('Item 2');
    expect(itemTexts).toContain('Item 3');
    expect(itemTexts).toContain('Item 4');
  });

  test('should handle drag and drop with keyboard accessibility', async ({ page }) => {
    const listItems = page.getByRole('listitem');

    // Focus on first item
    await listItems.nth(0).focus();

    // Verify item is focused
    await expect(listItems.nth(0)).toBeFocused();

    // Perform drag operation
    const item1 = listItems.nth(0);
    const item2 = listItems.nth(1);

    await item1.dragTo(item2);
    await page.waitForTimeout(100);

    // Verify reorder occurred
    const updatedItems = page.getByRole('listitem');
    await expect(updatedItems.nth(0)).toContainText('Item 2');
    await expect(updatedItems.nth(1)).toContainText('Item 1');
  });
});
